from pathlib import Path
import json
R=Path.cwd();O=R/'outputs/expanded'
manifest=json.loads((O/'scout_manifest.json').read_text());
if (O/'new_scout_manifest.json').exists():manifest+=json.loads((O/'new_scout_manifest.json').read_text())
rows=[]
for r in manifest:
 p=O/'scouting'/f"{r['id']}.json"
 rows.append(dict(**r,scout=json.loads(p.read_text()) if p.exists() else None))
(O/'scout_data.json').write_text(json.dumps(rows,indent=2))
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MMA / Expanded evidence laboratory</title><style>
:root{color-scheme:dark;--bg:#10171c;--panel:#18232a;--ink:#edf0e9;--muted:#a3b0b7;--cyan:#22d3ee;--coral:#fb7185}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:40px}a{color:var(--cyan)}.kicker{letter-spacing:2px;font-size:12px;color:var(--cyan)}h1{font-size:clamp(34px,5vw,65px);font-weight:550;letter-spacing:-2px;line-height:1.1;margin:16px 0}h2{font-size:24px;font-weight:550}p{color:var(--muted);max-width:900px}header{border-bottom:1px solid #36464e;padding-bottom:22px}.stats{display:flex;gap:28px;flex-wrap:wrap;margin:25px 0}.stat strong{display:block;font-size:31px;font-weight:550}.stat span{color:var(--muted)}.palette{display:flex;gap:20px;align-items:center;margin:18px 0}.dot{width:12px;height:12px;border-radius:50%;display:inline-block;margin-right:6px}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}input,select,button{background:#1c2a33;color:var(--ink);border:1px solid #485e69;border-radius:6px;padding:10px;font:inherit}input{flex:1;min-width:240px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:20px}.card{background:var(--panel);border:1px solid #35434a;border-radius:12px;overflow:hidden}.card img{width:100%;display:block}.card .body{padding:16px}.tag{display:inline-block;font-size:12px;padding:3px 7px;border:1px solid #44555f;border-radius:4px;margin:0 5px 6px 0;color:#c1d1d7}.status{color:var(--cyan)}.muted{color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.55 ui-monospace,monospace}details{margin-top:12px}summary{cursor:pointer;color:var(--cyan)}.identity{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:20px}.identity img{width:100%}.note{border-left:2px solid var(--coral);padding:10px 16px;margin:26px 0;background:#1b252b}video{width:100%;background:black}footer{margin-top:36px;border-top:1px solid #36464e;padding-top:20px;color:var(--muted)}@media(max-width:650px){main{padding:20px}.identity{grid-template-columns:1fr}}
</style></head><body><main><header><div class="kicker">MMA / EXPANDED EVIDENCE LABORATORY</div><h1>Read the exchange.<br>Follow each fighter.</h1><p>Detailed body figures, visible actions, responses, and traceable frame evidence. An expanding research collection for movement, fight evolution, search, and anticipation.</p><a href="../experiment/index.html">Original causal experiments ↗</a></header><div class="stats"><div class="stat"><strong id="windows">—</strong><span>systematic scout windows</span></div><div class="stat"><strong id="ready">—</strong><span>Sol scout reviews available</span></div><div class="stat"><strong>133</strong><span>RTMW landmarks per estimated pose</span></div></div><div class="palette"><span><i class="dot" style="background:var(--cyan)"></i>Cyan figure</span><span><i class="dot" style="background:var(--coral)"></i>Coral figure</span><span><i class="dot" style="background:#a1a1aa"></i>Unassigned ownership</span></div><div class="note">Work in progress. Scout sheets sample roughly every 2.7 seconds and identify useful sequences; they cannot establish impact timing or clean contact. Colored figures use identity evidence, while merged or uncertain bodies remain unassigned. Detailed annotation is a separate layer.</div><p><a href="assessment/index.html">Graded possibility map ↗</a> · <a href="key_moments/subtypes/index.html">Prediction by strike type & phase ↗</a> · <a href="segmentation/index.html">Limb ownership experiments ↗</a></p><h2>Identity and whole-body figures</h2><p><a href="motion.html">Open video / figure-only motion study ↗</a></p><div class="identity" id="identity"></div><h2>Read the movement frame by frame</h2><p><a href="frame_lab/index.html">Open the native frame annotation bench ↗</a> · Slow motion, magnifier, contact claims, and later corrections beside the video.</p><h2>New detailed sequences</h2><p><a href="annotation_bundle.json">Reviewed labels + fine-detail corrections ↗</a> · <a href="key_moments/index.html">Key-moment forecast laboratory ↗</a> · <a href="causal_v2/index.html">First-action study (secondary) ↗</a> · <a href="causal_preview/index.html">Four-case preview ↗</a> · <a href="mcgregor/index.html">McGregor movement evidence ↗</a></p><p>Full-frame evidence preserves hands and feet when the broadcast view includes them. Independent model review can challenge labels; it does not substitute for expert ground truth.</p><div class="grid" id="detailed"></div><h2>Explore the broader evidence</h2><div class="filters"><input id="query" placeholder="Search visible action, control, or uncertainty" aria-label="Search scout evidence"><select id="phase" aria-label="Filter phase"><option value="">All phases</option><option>standing</option><option>clinch</option><option>ground</option></select><button id="refresh">Refresh available reviews</button></div><div class="grid" id="scouts"></div><footer><a href="morning-report.txt">Morning research report</a> · <a href="research-plan.txt">Research plan</a> · <a href="scout_manifest.json">Source-time manifest</a> · <a href="root_source.json">New source provenance</a><p>Model-reviewed observations and uncertain estimates. No newly trained model. Source windows from one bout are correlated; overlapping windows are not independent evidence.</p></footer></main><script>
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[];
async function get(p){const r=await fetch(p+'?v='+Date.now());if(!r.ok)throw new Error(p);return r.json()}
function render(){let q=$('query').value.toLowerCase(),ph=$('phase').value;let filtered=rows.filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!ph||r.scout?.phases_seen?.includes(ph)));$('scouts').innerHTML=filtered.map(r=>`<article class="card"><a href="${esc(r.evidence)}"><img loading="lazy" src="${esc(r.evidence)}" alt="${r.id} nine timestamped scouting frames"></a><div class="body"><strong>${r.id} · ${esc(r.source.replaceAll('-',' '))}</strong><div class="muted">Source ${r.start}–${r.end.toFixed(1)}s · ${r.duration.toFixed(1)} seconds</div><p class="status">${r.scout?esc(r.scout.phases_seen.join(' → ')):'Sol scouting in progress'}</p>${(r.scout?.useful_for||[]).map(t=>`<span class="tag">${esc(t.replaceAll('_',' '))}</span>`).join('')}<details><summary>Inspect scout data</summary><pre>${esc(JSON.stringify(r.scout||{status:'pending'},null,2))}</pre></details></div></article>`).join('')}
async function load(){const m=(await Promise.all([get('scout_manifest.json'),get('new_scout_manifest.json').catch(()=>[])])).flat();rows=await Promise.all(m.map(async r=>{try{return {...r,scout:await get('scouting/'+r.id+'.json')}}catch{return {...r,scout:null}}}));$('windows').textContent=rows.length;$('ready').textContent=rows.filter(r=>r.scout).length;render();let detailed=[];try{let m=(await Promise.all([get('annotation_manifest.json'),get('annotation_manifest_extra.json').catch(()=>[])])).flat();for(const r of (Array.isArray(m)?m:Object.values(m))){let id=r.id||r.clip_id;if(!id)continue;let a=null;try{a=await get('annotations/'+id+'.json')}catch{}detailed.push(`<article class="card"><video controls preload="metadata" src="clips/${id}.mp4"></video><div class="body"><strong>Clip ${esc(id)} · detailed sequence</strong><p>${a?'Reviewed annotation available':'Annotation incomplete; video evidence available'}</p>${a?`<a href="annotations/${id}.json">Annotation JSON ↗</a> · <a href="annotations/${id}_detail.json">Fine-detail challenge ↗</a>`:`<span class="muted">No finished labels claimed.</span>`}<details><summary>Inspect labels</summary><pre>${esc(JSON.stringify(a||r,null,2))}</pre></details></div></article>`)}}catch{}$('detailed').innerHTML=detailed.join('')}
$('identity').innerHTML=['A','B','C','D','E','F','G','H'].map(c=>`<article class="card"><a href="identity/${c}-identity-contact.jpg"><img loading="lazy" src="identity/${c}-identity-contact.jpg" alt="Clip ${c} figure identity evidence at six times"></a><div class="body"><strong>Clip ${c} · identity candidates across time</strong><p>Clothing and temporal association; unknown identities stay gray.</p><a href="identity/${c}-identities.json">Frame identity data ↗</a> · <a href="color_videos/${c}-colored-figures.mp4">Colored figure video ↗</a></div></article>`).join('');$('query').oninput=render;$('phase').onchange=render;$('refresh').onclick=load;load().catch(e=>{$('scouts').textContent='Could not load evidence: '+e.message});
</script></body></html>'''
(O/'index.html').write_text(html)
print('Expanded viewer built')
